import{_ as s,C as n,o as i,c as r,a2 as e,E as o}from"./chunks/framework.9yf7n3zg.js";const h="/guide/media/inbox-overview.webp",d="/guide/media/inbox-conflict.webp",c="/guide/media/inbox-review.webp",l="/guide/media/inbox-tags-table.webp",g="/guide/media/inbox-layer-beats.webp",p="/guide/media/inbox-proposals-sheet.webp",k=JSON.parse('{"title":"Proposals and the inbox","description":"","frontmatter":{},"headers":[],"relativePath":"guide/inbox.md","filePath":"guide/inbox.md","lastUpdated":1792171429000}'),u={name:"guide/inbox.md"};function m(w,t,y,f,b,v){const a=n("Clip");return i(),r("div",null,[t[0]||(t[0]=e('<h1 id="proposals-and-the-inbox" tabindex="-1">Proposals and the inbox <a class="header-anchor" href="#proposals-and-the-inbox" aria-label="Permalink to &quot;Proposals and the inbox&quot;">​</a></h1><p>A connected agent never writes your files. What it wants changed it proposes as a <strong>changeset</strong>: a short list of numbered items with a reason, which waits for you. Every changeset says which views it changes. You can read it in the <strong>Inbox</strong>, or review it in the view itself, with each proposal drawn where it would land. Only your accept writes anything, and only to Leathercase&#39;s own files, never to your manuscript. This page covers changesets, the inbox, reviewing in a view, the proposed layer on each view, the keys to walk and answer proposals, and what happens when you have changed something an agent proposed to change.</p><p>To let an agent propose, connect it with the <strong>Assist</strong> or <strong>Lay out</strong> toolset; see <a href="/guide/guide/connect-an-agent">Connect an agent</a>. The mate&#39;s findings also appear on the layer and in the inbox; see <a href="/guide/guide/mate#findings-beside-your-scenes">The mate</a>.</p><h2 id="what-an-agent-can-propose" tabindex="-1">What an agent can propose <a class="header-anchor" href="#what-an-agent-can-propose" aria-label="Permalink to &quot;What an agent can propose&quot;">​</a></h2><p>Each item of a changeset is one change. With <strong>Assist</strong>, an agent may propose comments, threads and facts. With <strong>Lay out</strong>, it may also propose changes to the beat board, the plot grid and the Graph, and how a story&#39;s unsorted files should be read.</p><p>Each item is named by what it does, and grouped under the view it changes.</p><table tabindex="0"><thead><tr><th>View</th><th>Item</th><th>Toolset</th><th>What accepting it writes</th></tr></thead><tbody><tr><td><a href="/guide/guide/plot-grid">Plot grid</a></td><td><strong>Add a column</strong></td><td>Lay out</td><td>A new, empty column of the plot grid: an arc, a theme, a subplot or a free one, with a line about it</td></tr><tr><td></td><td><strong>Plan a scene</strong></td><td>Lay out</td><td>A planned row of the plot grid, a scene not written yet, with its summary: after a row, or at the end of a chapter and part, made when the grid has none of that name (<code>PlotGrid.md</code>)</td></tr><tr><td></td><td><strong>Change a summary</strong></td><td>Lay out</td><td>A row&#39;s summary: what happens in the scene, in a line or two (<code>PlotGrid.md</code>)</td></tr><tr><td></td><td><strong>Fill a cell</strong></td><td>Lay out</td><td>A plot grid cell filled, or emptied, on a written row or a planned one; with its word on the column&#39;s scale, its role and the sentence that shows it</td></tr><tr><td></td><td><strong>Give a column a job</strong></td><td>Lay out</td><td>Which column is the point of view, the time, the main theme or the beats</td></tr><tr><td><a href="/guide/guide/threads">Threads</a></td><td><strong>Draw a thread</strong></td><td>Assist</td><td>A new thread through some scenes, in the story&#39;s threads note (<code>StoryThreads.md</code>); it becomes a column of the plot grid</td></tr><tr><td><a href="/guide/guide/beat-board">Beat board</a></td><td><strong>Make a card</strong> · <strong>Move a card</strong></td><td>Lay out</td><td>A new card on a beat or loose, or a card moved to another beat or another place in its column</td></tr><tr><td></td><td><strong>Choose a framework</strong></td><td>Lay out</td><td>The beat board&#39;s framework</td></tr><tr><td></td><td><strong>Tag a card</strong></td><td>Lay out</td><td>A tag on a beat card</td></tr><tr><td><a href="/guide/guide/graph">Graph</a></td><td><strong>Make a note</strong></td><td>Lay out</td><td>A note Leathercase keeps for a character, place, item, faction or event the story names: a name in the Graph</td></tr><tr><td></td><td><strong>Draw a tie</strong></td><td>Lay out</td><td>A tie in the Graph between two names, with its type, its word, its side and, for a tie that looks one way and is another, the Plot grid beat where it comes out; one line of <code>Graph/Ties.md</code></td></tr><tr><td></td><td><strong>Change a tie</strong></td><td>Lay out</td><td>A tie the Graph has, changed. One written in a note or on the old story map moves into <code>Graph/Ties.md</code>; your note stays as it was</td></tr><tr><td></td><td><strong>Make a Graph tab</strong> · <strong>Give a role</strong></td><td>Lay out</td><td>A tab of the Graph, blank or from a template, and a role for a name in it (hero, main opponent, ally), in the tab&#39;s own file</td></tr><tr><td><a href="/guide/guide/characters">Characters</a></td><td><strong>Fill a section</strong> · <strong>Add a past event</strong></td><td>Lay out</td><td>A section of a character&#39;s sheet, or an event of their past, in the note Leathercase keeps for them</td></tr><tr><td></td><td><strong>Set a pronoun</strong> · <strong>Add another name</strong></td><td>Lay out</td><td>A character&#39;s pronoun, or another name for them, in the story&#39;s settings</td></tr><tr><td></td><td><strong>Mark a fact</strong></td><td>Assist</td><td>A fact about the story, resting on a sentence quoted from a scene, in <code>Facts.md</code>; shown on the sheet of each character it names</td></tr><tr><td><a href="/guide/guide/tags">Tags</a></td><td><strong>Add a tag</strong> · <strong>Tag a scene</strong></td><td>Lay out</td><td>A tag in the home&#39;s tags with what it means, or a tag on a scene (in <code>PlotGrid.md</code>)</td></tr><tr><td><a href="/guide/guide/manuscript">Manuscript</a></td><td><strong>Leave a comment</strong></td><td>Assist</td><td>A comment on a scene, or on a quoted passage of it, in the story&#39;s comments (<code>Comments.md</code>)</td></tr><tr><td><a href="/guide/guide/how-a-story-is-read">How this story is read</a></td><td><strong>Sort files</strong> · <strong>Set images</strong></td><td>Lay out</td><td>What a group of unsorted files holds (prose, plans, characters…), written into the story&#39;s declaration; or the images a symbol is found by in the prose, kept in Leathercase&#39;s note beside yours</td></tr></tbody></table><h3 id="items-that-go-together" tabindex="-1">Items that go together <a class="header-anchor" href="#items-that-go-together" aria-label="Permalink to &quot;Items that go together&quot;">​</a></h3><p>Some items stand on others in the same changeset: a tie drawn to a note the changeset also makes, a role in a tab it also makes, a cell in a column it also adds, a tag on a scene for a tag it also adds. They go together:</p><ul><li>Accepting an item accepts what it stands on. The button says so: <strong>Accept, with item 1</strong>.</li><li>Dismissing an item dismisses what stands on it: <strong>Dismiss, with items 8, 9 and 10</strong>.</li></ul><p>So a tie can never point at a note you turned down. In the inbox, an item that stands on another sits right under it.</p><h3 id="what-an-agent-laid-out-stays-marked" tabindex="-1">What an agent laid out stays marked <a class="header-anchor" href="#what-an-agent-laid-out-stays-marked" aria-label="Permalink to &quot;What an agent laid out stays marked&quot;">​</a></h3><p>A row title, a summary, a column or a cell you accept from an agent is drawn with a light grey wash and a dotted line under it: generated. Hover it to read it whole and to see that it came from an agent. The mark stays after you accept it and goes the first time you edit the text, in Leathercase or in another editor. If you change the text in the inbox before you accept it, it is yours from the start and carries no mark.</p><p>In the files, the mark is a comment beside the text, <code>&lt;!-- generated: summary · 3kq9xz --&gt;</code>, with a short hash of the words you accepted. Delete it to take the mark off by hand.</p><p>In the Graph, a note or a tie an agent laid out is drawn the same way, and its hover names the agent. A tie you accept carries a <code>by:</code> line under it in <code>Graph/Ties.md</code>, with the agent&#39;s name, until you change the tie in the app.</p><p>All of these are files Leathercase writes for you, in the story&#39;s <code>suite/</code> folder or the author data folder you chose, never the source files you write in. See <a href="/guide/reference/suite-files">Files Leathercase writes</a>.</p><p>Besides changesets, an agent with <strong>Assist</strong> can leave two kinds of notes beside a scene, which are not proposals and change nothing:</p><ul><li>a <strong>finding</strong>: something it noticed, such as a continuity slip or a name used two ways;</li><li>a <strong>comment</strong>: a remark addressed to you, which you can take into your own comments.</li></ul><h3 id="every-proposal-has-a-reason-and-every-text-passes-the-gate" tabindex="-1">Every proposal has a reason, and every text passes the gate <a class="header-anchor" href="#every-proposal-has-a-reason-and-every-text-passes-the-gate" aria-label="Permalink to &quot;Every proposal has a reason, and every text passes the gate&quot;">​</a></h3><p>An agent must say why it proposes something; a changeset without a reason is refused back to the agent. Quotes must be in their scene word for word. Every text an agent sends, from a card&#39;s title to a comment, has hidden characters (zero-width spaces, direction marks, odd spaces) taken out before you see it. You can edit any text item before you accept it, and the edited text is then yours.</p><h2 id="the-inbox" tabindex="-1">The inbox <a class="header-anchor" href="#the-inbox" aria-label="Permalink to &quot;The inbox&quot;">​</a></h2><p>The inbox is the home&#39;s place for what agents proposed, for every story in it. Open it with:</p><ul><li><strong>Inbox</strong> in the sidebar, which shows &quot;2 to review&quot; when changesets wait;</li><li><code>Ctrl+0</code> (<code>Cmd+0</code> on macOS), or <strong>Inbox</strong> in the <strong>View</strong> menu;</li><li><strong>Inbox</strong> in the agents menu of the title bar;</li><li><strong>In the inbox ›</strong> on a changeset in a view&#39;s Proposals sheet;</li><li><strong>open it</strong> on a line that says where something you have came from;</li><li>a link an agent gives you (see <a href="#links-to-a-changeset">Links to a changeset</a>).</li></ul><p><img src="'+h+'" alt="The inbox with a changeset from Cowork open: the views it changes in the list, its reason, and its items grouped under Plot grid" width="1130" height="852" loading="lazy"></p><p>Its header has two tabs, <strong>Changesets</strong> and <strong>Findings</strong> (the mate&#39;s; see <a href="/guide/guide/mate#findings-in-the-inbox">The mate</a>), and a state line such as &quot;2 to review · 1 proposed · 1 stale · 0 partial · 3 accepted · 1 dismissed&quot;.</p><p>With nothing proposed yet, it says: &quot;No agent has proposed anything for this home&#39;s stories yet. What an agent proposes waits here, never in your files.&quot;</p><h3 id="the-list" tabindex="-1">The list <a class="header-anchor" href="#the-list" aria-label="Permalink to &quot;The list&quot;">​</a></h3><p>On the left, the changesets, grouped by story (&quot;The Lamp at Ferrol · 2&quot;). Three filters sit at the top, each with its count:</p><table tabindex="0"><thead><tr><th>Filter</th><th>Shows changesets that are</th></tr></thead><tbody><tr><td><strong>To review</strong></td><td>proposed, stale or partial</td></tr><tr><td><strong>Accepted</strong></td><td>accepted whole</td></tr><tr><td><strong>Dismissed</strong></td><td>dismissed whole</td></tr></tbody></table><p>Each line gives the changeset&#39;s title in italics, its status, the views it changes with their icons and how many items each (&quot;Plot grid 3&quot;, &quot;Tags 27&quot;), the agent&#39;s tag, and &quot;revision 1 · 2 of 4 waiting · 14:02&quot;, where waiting counts the items still pending and those back in conflict. A filter with nothing in it says &quot;Nothing here.&quot; At the foot: &quot;each changeset is also a markdown file, in the story&#39;s suite/assistant/changesets&quot;.</p><p>With nothing picked, the newest changeset that waits opens on the right.</p><p><strong>Drafts.</strong> An agent may save a large changeset as a draft while it talks it over with you, for example to ask which of two letters Anna reads. A <strong>Drafts</strong> tab appears while one exists: you can read the draft there, not answer it yet. It moves to <strong>To review</strong> when the agent submits it.</p><h3 id="a-changeset" tabindex="-1">A changeset <a class="header-anchor" href="#a-changeset" aria-label="Permalink to &quot;A changeset&quot;">​</a></h3><p>On the right, the changeset you picked:</p><ul><li>its <strong>title</strong> and <strong>status</strong>;</li><li>who sent it and from what: the agent, the model it reported (&quot;model …, as reported&quot;), the revision, the story and the time;</li><li>three links: <strong>Open the file in your software</strong> (its markdown copy), <strong>Copy its link for</strong> the agent, and <strong>Show</strong> the story;</li><li>the agent&#39;s <strong>reason</strong>, in its own words;</li><li>the <strong>items</strong>, grouped under the view each changes, with <strong>Review in</strong> that view; each item numbered, named by what it does (&quot;Fill a cell&quot;), with one sentence saying what exactly;</li><li>the buttons that answer the whole changeset;</li><li>its <strong>Revisions</strong>.</li></ul><p>The changeset&#39;s statuses:</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td>proposed</td><td>Waiting for you</td></tr><tr><td>stale</td><td>You changed what it touches after it was written; see <a href="#when-you-changed-it-meanwhile">Conflicts</a></td></tr><tr><td>partial</td><td>Some items accepted, the rest dismissed or still in conflict</td></tr><tr><td>accepted</td><td>Every item accepted</td></tr><tr><td>dismissed</td><td>Dismissed whole; kept, so it is not offered again</td></tr></tbody></table><p>An item&#39;s badge says <strong>touched since</strong> (you changed it after the agent wrote the item), <strong>applied</strong> with the time, <strong>conflict · back as stale</strong>, or <strong>dismissed</strong>. An item waiting that nothing has touched has no badge.</p><h3 id="answering-item-by-item" tabindex="-1">Answering item by item <a class="header-anchor" href="#answering-item-by-item" aria-label="Permalink to &quot;Answering item by item&quot;">​</a></h3><p>Each waiting item shows only what helps you decide:</p><table tabindex="0"><thead><tr><th>The item</th><th>What you see</th></tr></thead><tbody><tr><td>Adds something new (a card, a tag, a planned scene)</td><td>What will be there. For a text, an editable box: &quot;proposed · edit to change&quot;</td></tr><tr><td>Changes something you wrote (a summary, a cell)</td><td><strong>yours</strong> beside the proposal</td></tr><tr><td>Changes something you changed since it was proposed</td><td>&quot;You changed this since it was proposed.&quot;, what you have now beside the proposal, and <strong>What it said when they proposed this</strong> to see the value it was written against</td></tr><tr><td>Has nothing to show but its sentence (a tag on a scene, a moved card)</td><td>The sentence alone</td></tr></tbody></table><p>Type in the proposed box and its label becomes &quot;edited by you&quot;, and the button becomes <strong>Accept edited</strong>. Under each item:</p><ul><li><strong>Accept</strong> (or <strong>Accept edited</strong>) writes this item, with any item it stands on.</li><li><strong>Dismiss</strong> leaves it, with any item standing on it.</li><li>On an item you changed since, the buttons read <strong>Keep mine, dismiss this item</strong> first, then <strong>Use theirs</strong>.</li></ul><p>An item accepted as you edited it then says &quot;accepted as you edited it:&quot; followed by your value.</p>',44)),o(a,{name:"inbox-edit-accept",caption:"Editing a proposed card title in the inbox, then pressing Accept edited"}),t[1]||(t[1]=e('<h3 id="after-you-accept" tabindex="-1">After you accept <a class="header-anchor" href="#after-you-accept" aria-label="Permalink to &quot;After you accept&quot;">​</a></h3><p>Above the items, the inbox says what changed and where: &quot;3 changes made&quot;, then a line per view, &quot;Plot grid: 2&quot;, &quot;Tags: 1&quot;. <strong>Show it</strong>, beside a story view, opens that view.</p><h3 id="answering-the-whole-changeset" tabindex="-1">Answering the whole changeset <a class="header-anchor" href="#answering-the-whole-changeset" aria-label="Permalink to &quot;Answering the whole changeset&quot;">​</a></h3><p>Below the items:</p><ul><li><strong>Accept all 4</strong> writes every waiting item, with any edits you typed.</li><li>When some items were touched since, the button reads <strong>Accept all, merge each</strong>, and a second button, <strong>Accept the 3 clean items</strong>, writes only the items nothing has touched.</li><li><strong>Dismiss the changeset</strong> dismisses what is left.</li><li>A faint line: &quot;talk it over in Cowork · it revises, every revision is kept&quot;. To change a proposal, ask the agent in its own app; it sends a new revision.</li></ul><p>While an accept is being written, the accept buttons wait, so a double click writes once.</p><h3 id="revisions" tabindex="-1">Revisions <a class="header-anchor" href="#revisions" aria-label="Permalink to &quot;Revisions&quot;">​</a></h3><p>Every revision of a changeset is kept. <strong>Revisions</strong> at the foot says how many (&quot;2 revisions kept&quot;) and lists them, newest first, with the time and title; the current one says &quot;this one&quot;. <strong>show</strong> opens an earlier revision read-only, with its reason and its items as they were; <strong>hide</strong> folds it.</p><p>You accept only the revision you read. If the agent revised the changeset while you were reading it, your accept is turned down and the changeset is shown again as it stands now, under <strong>Not accepted.</strong>: &quot;The changeset changed while you read it, or part of it could not be written. Here it is again as it stands now; nothing was written twice.&quot;</p><h2 id="when-you-changed-it-meanwhile" tabindex="-1">When you changed it meanwhile <a class="header-anchor" href="#when-you-changed-it-meanwhile" aria-label="Permalink to &quot;When you changed it meanwhile&quot;">​</a></h2><p>An agent writes each item against your files as they were. If you change what an item touches before you answer, for example you fill the POV cell of a scene the agent also proposed to fill, Leathercase never overwrites your change.</p><ul><li>The item is marked <strong>touched since</strong> and says &quot;You changed this since it was proposed.&quot;, with your value beside the proposal.</li><li>If you changed what the whole changeset rests on, it is <strong>stale</strong>: &quot;You changed what it touches after it was written. Accept still tries each item three ways: the ones you have not touched apply; the others come back.&quot;</li><li>When you accept, the clean items are written; the touched ones become <strong>conflict · back as stale</strong>, and Leathercase says, for example, &quot;Accepted 1 of 2. One item conflicted.&quot; and &quot;You changed what it touched after it was written. The clean items are in. The rest goes back to Cowork as stale; it sees that on its next call.&quot; This sentence is said once.</li><li>On an item in conflict you can <strong>Keep mine, dismiss this item</strong>, or wait: &quot;when Cowork rebases, this item comes back as a new revision.&quot;</li></ul><p>If a write fails part way, the items already written stay written, and accepting again writes only what is left. Nothing is written twice.</p><p><img src="'+d+'" alt="A changeset whose item 3 says &quot;You changed this since it was proposed.&quot;, with the writer&#39;s &quot;Sabela Vidal&quot; beside the proposal and Keep mine first, after &quot;Accepted 2 of 3. One item conflicted.&quot;" width="677" height="639" loading="lazy"></p><div class="info custom-block"><p class="custom-block-title">Conflicted copies from a sync tool are something else</p><p>When a sync tool such as Dropbox or iCloud keeps two versions of one of Leathercase&#39;s files, they are listed under <strong>Settings › Storage</strong>, with <strong>Compare</strong>, <strong>Keep the copy</strong> and <strong>Keep this computer&#39;s</strong>. See <a href="/guide/reference/settings#conflicted-copies">Settings</a>.</p></div><h2 id="reviewing-in-a-view" tabindex="-1">Reviewing in a view <a class="header-anchor" href="#reviewing-in-a-view" aria-label="Permalink to &quot;Reviewing in a view&quot;">​</a></h2><p>A changeset is easiest to judge where it would land. <strong>Review in Plot grid</strong> (or in whichever view a group of items changes) opens the story on that view, with the proposals drawn in place and a <strong>review bar</strong> in the side column:</p><ul><li><strong>Reviewing</strong>, the changeset&#39;s title, the agent, the model it reported and the revision;</li><li>the agent&#39;s reason;</li><li>the views the changeset changes, as buttons with how many items each; click one to go there, the review stays open;</li><li>how far you are: &quot;2 of 7 decided&quot;;</li><li>this view&#39;s proposals, each with <strong>Accept</strong>, <strong>Edit, then accept</strong> and <strong>Dismiss</strong>;</li><li><strong>Accept the rest</strong>, which accepts every item still waiting, in every view, and <strong>Show as a list</strong>, which opens the changeset in the inbox.</li></ul><p>During a review the proposals are drawn even if you have hidden the assistant&#39;s layer. Leaving the story, or the close button of the bar (<strong>End the review</strong>), ends the review; what you decided stays decided, and the changeset waits in the inbox with what is left. When nothing is left to decide the bar says &quot;Every item is decided. The changeset stays in the inbox with what you answered.&quot; A view with none of this changeset&#39;s items says &quot;Nothing in this view. The rest is in the views above.&quot;</p><p><img src="'+c+'" alt="The plot grid of The Lamp at Ferrol with the review bar of &quot;Weather through act two&quot; in the side column" width="375" height="765" loading="lazy"></p><h3 id="keys-during-a-review" tabindex="-1">Keys during a review <a class="header-anchor" href="#keys-during-a-review" aria-label="Permalink to &quot;Keys during a review&quot;">​</a></h3><p>While a review is open, single keys walk and answer this view&#39;s proposals. They do nothing while you are typing in a field.</p><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>Tab</code> · <code>Shift+Tab</code></td><td>Picks the next or previous proposal of this view, and moves the focus to it. Only from the page or a proposal: from any other button or field, Tab moves between controls as it always does</td></tr><tr><td><code>A</code></td><td>Accepts the picked proposal</td></tr><tr><td><code>D</code></td><td>Dismisses it</td></tr><tr><td><code>E</code></td><td>Opens its text to edit, then <strong>Accept edited</strong></td></tr></tbody></table><h3 id="tags-as-a-table" tabindex="-1">Tags as a table <a class="header-anchor" href="#tags-as-a-table" aria-label="Permalink to &quot;Tags as a table&quot;">​</a></h3><p>Tags are reviewed in the inbox, as a table: <strong>Review in Tags</strong> on a changeset&#39;s tags turns the list into a row per tag, with what it means, and a column per scene in reading order, a dot where the changeset puts that tag on that scene. The dot&#39;s number is the item&#39;s place in the changeset.</p><ul><li><strong>Accept · 4</strong> on a row accepts the tag with all its scenes.</li><li><strong>Dismiss, with its scenes</strong> dismisses the tag and every scene tag that stands on it.</li><li>Pick a dot to answer that scene alone, below the table.</li></ul><p><strong>Show as a list</strong> turns the table back into the list. The <a href="/guide/guide/tags">Tags</a> view itself draws no proposals.</p><p><img src="'+l+'" alt="A changeset of three tags on five scenes reviewed as a table, each tag with what it means and Accept on its row" width="677" height="762" loading="lazy"></p><h2 id="the-assistant-s-layer" tabindex="-1">The assistant&#39;s layer <a class="header-anchor" href="#the-assistant-s-layer" aria-label="Permalink to &quot;The assistant&#39;s layer&quot;">​</a></h2><p>What agents propose for a story is drawn on its views, so you can answer in place. Everything proposed has the proposal style (a dashed frame and italic text) and a small tag with the agent and the item&#39;s number, such as &quot;Cowork · 1&quot;. Findings and comments carry &quot;finding · Cowork&quot; or &quot;comment · Cowork&quot;; the mate&#39;s carry its pulse mark and &quot;the mate&quot;.</p><table tabindex="0"><thead><tr><th>View</th><th>What is drawn</th></tr></thead><tbody><tr><td><a href="/guide/guide/beat-board">Beat board</a></td><td>Proposed cards at the foot of their beat&#39;s column; a proposed move as a tag on the card, &quot;move after The lamp&quot;</td></tr><tr><td><a href="/guide/guide/plot-grid">Plot grid</a></td><td>A proposed column at the right, headed &quot;proposed column&quot;; a proposed value under the cell it would fill; a proposed summary under the row&#39;s summary; a planned row at the foot, &quot;planned row, proposed&quot;</td></tr><tr><td><a href="/guide/guide/graph">Graph</a></td><td>A proposed tie as a dashed line between its two names, with its word on it; its hover says who proposed it. A tie to a name the tab does not show is not drawn. Answer it in the inbox, the review bar or the Proposals sheet</td></tr><tr><td><a href="/guide/guide/manuscript">Manuscript</a></td><td>Under each scene&#39;s heading: proposed comments and facts, and the findings and comments agents left on that scene</td></tr><tr><td><a href="/guide/guide/threads">Threads</a>, chart and lanes</td><td>A <strong>Proposed</strong> section with each proposed thread and &quot;through 4 scenes&quot;</td></tr></tbody></table><p>Hover or focus a proposal to see its popover: the kind, the sentence, the changeset, the agent, the model it reported, the revision and status, and the three answers <strong>Accept</strong>, <strong>Edit, then accept</strong> (for a text) and <strong>Dismiss</strong>. <strong>Edit, then accept</strong> opens the text in a box; once you type, it is &quot;edited by you&quot;, and <strong>Cancel</strong> closes the box.</p><p><img src="'+g+'" alt="The beat board of The Lamp at Ferrol with two cards proposed by Cowork at the foot of the Midpoint column" width="1105" height="431" loading="lazy"></p><p>At the right of a view&#39;s header, a tag button says &quot;3 proposed here&quot;. It counts only what this view draws: the cards on the beat board, the cells, columns, summaries and planned rows on the plot grid, the threads on the threads chart, the ties on the Graph, and on the manuscript the comments, facts and findings left on a scene. A view that draws none of what waits shows no tag; the Proposals sheet still lists everything for the story. The button opens that sheet.</p><h3 id="hiding-the-layer" tabindex="-1">Hiding the layer <a class="header-anchor" href="#hiding-the-layer" aria-label="Permalink to &quot;Hiding the layer&quot;">​</a></h3><p>Press <code>Ctrl+.</code> (the command <strong>Show or hide the assistant&#39;s layer</strong>, in the <strong>View</strong> menu) to hide everything agents and the mate left on the views. The view&#39;s header then says how many of this view&#39;s proposals are hidden, &quot;2 hidden&quot;, and the Proposals sheet says &quot;The layer is off: 2 hidden in the views.&quot; Press it again to bring them back. Leathercase remembers your choice the next time it starts. Hiding the layer changes nothing in the inbox.</p>',36)),o(a,{name:"inbox-layer-toggle",caption:"Turning the assistant's layer off with Ctrl+. on the beat board, then on again"}),t[2]||(t[2]=e('<h3 id="where-something-came-from" tabindex="-1">Where something came from <a class="header-anchor" href="#where-something-came-from" aria-label="Permalink to &quot;Where something came from&quot;">​</a></h3><p>After you accept an item or take a comment, the view keeps a faint line beside what it made: &quot;accepted from Cowork&#39;s changeset, item 1, 14:02 · open it&quot;, &quot;accepted, as you edited it, from …&quot;, or &quot;taken from Cowork&#39;s comment · 14:02&quot;. You find it in a beat card&#39;s side column, a grid cell&#39;s section, and under a scene&#39;s heading in the manuscript. <strong>open it</strong> opens the changeset in the inbox.</p><h2 id="the-proposals-sheet" tabindex="-1">The Proposals sheet <a class="header-anchor" href="#the-proposals-sheet" aria-label="Permalink to &quot;The Proposals sheet&quot;">​</a></h2><p>In a story view, the Proposals sheet takes the side column and lists what waits on this story. Open it with:</p><ul><li><code>Ctrl+Shift+.</code>, the command <strong>Proposals for this story</strong>;</li><li>the &quot;N proposed here&quot; button in the view&#39;s header;</li><li><code>Ctrl+]</code> or <code>Ctrl+[</code>, which open it and pick a proposal.</li></ul><p>Its header says how many changesets, with a close button (<strong>Close the proposals</strong>). <code>Ctrl+B</code> also closes it.</p><p><img src="'+p+'" alt="The Proposals sheet in the plot grid&#39;s side column with Cowork&#39;s changesets and one comment, and the proposed Weather column in the grid" width="504" height="1100" loading="lazy"></p><p>For each changeset: its title, &quot;Cowork · revision 1 · 2 waiting · proposed&quot;, its reason, and each waiting item with its number, kind, conflict or &quot;touched since&quot; label, the sentence (click it to pick the item and highlight it on the view), and <strong>Accept</strong>, <strong>Edit, then accept</strong>, <strong>Dismiss</strong>. Then <strong>Accept all 2</strong>, <strong>Dismiss the changeset</strong>, and <strong>In the inbox ›</strong>.</p><p>Under <strong>Findings and comments</strong>, each finding and comment agents left on the story, with the scene&#39;s name and the quoted passage when there is one:</p><ul><li><strong>Open the scene</strong> opens it in the manuscript.</li><li><strong>Take</strong> (comments only) makes the comment yours: it is written into the story&#39;s comments, and leaves the layer.</li><li><strong>Dismiss</strong> hides it. A dismissed note is kept, with your answer, so the agent sees it was dismissed.</li><li><strong>Mute this rule</strong> (the mate&#39;s findings only) turns that rule off.</li></ul><p>With nothing waiting, the sheet says &quot;Nothing proposed for this story.&quot;</p><h2 id="keys-for-proposals" tabindex="-1">Keys for proposals <a class="header-anchor" href="#keys-for-proposals" aria-label="Permalink to &quot;Keys for proposals&quot;">​</a></h2><p>With a story open, these keys walk and answer proposals without the mouse, review or not. They work from any story view, and open the Proposals sheet if it is closed.</p><table tabindex="0"><thead><tr><th>Key</th><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>Ctrl+]</code></td><td><strong>Next proposal</strong></td><td>Picks the next waiting item; the view highlights it and the sheet scrolls to it</td></tr><tr><td><code>Ctrl+[</code></td><td><strong>Previous proposal</strong></td><td>Picks the previous one</td></tr><tr><td><code>Ctrl+Shift+Enter</code></td><td><strong>Accept the proposal</strong></td><td>Accepts the picked item, then picks the next</td></tr><tr><td><code>Ctrl+Shift+Backspace</code></td><td><strong>Dismiss the proposal</strong></td><td>Dismisses the picked item, then picks the next</td></tr><tr><td><code>Ctrl+Shift+.</code></td><td><strong>Proposals for this story</strong></td><td>Opens or closes the sheet</td></tr><tr><td><code>Ctrl+.</code></td><td><strong>Show or hide the assistant&#39;s layer</strong></td><td>Hides or shows everything proposed on the views</td></tr></tbody></table><p>On macOS, use <code>Cmd</code> for <code>Ctrl</code>. See <a href="/guide/reference/keys">Keys and commands</a>.</p>',15)),o(a,{name:"inbox-keys",caption:"Walking proposals on the plot grid with Ctrl+] and accepting one with Ctrl+Shift+Enter"}),t[3]||(t[3]=e('<h2 id="links-to-a-changeset" tabindex="-1">Links to a changeset <a class="header-anchor" href="#links-to-a-changeset" aria-label="Permalink to &quot;Links to a changeset&quot;">​</a></h2><p>Each changeset has a link of the form <code>leathercase://changeset/</code> followed by its id. An agent can give you that link in its own window; opening it brings Leathercase forward with the inbox open at that changeset, under a grey line such as &quot;opened from Cowork&#39;s link&quot;. <strong>Copy its link for</strong> the agent, in the changeset&#39;s header, puts the link on the clipboard (&quot;The link is on the clipboard.&quot;) so you can paste it to the agent when you talk the proposal over.</p><h2 id="changesets-as-files" tabindex="-1">Changesets as files <a class="header-anchor" href="#changesets-as-files" aria-label="Permalink to &quot;Changesets as files&quot;">​</a></h2><p>Each changeset is kept as two files in the story&#39;s <code>suite/assistant/changesets/</code> folder:</p><ul><li>a <code>.json</code> file, the exact items and every revision, which Leathercase reads;</li><li>a <code>.md</code> file beside it, a copy you can read without Leathercase, rewritten with every change. It lists each item in plain words (&quot;Make a card &quot;Mara reads the log&quot; on the beat &quot;Midpoint&quot;.&quot;), the reason under <strong>Why</strong>, and each item&#39;s state (applied; applied, edited by the writer; in conflict; dismissed).</li></ul><p>Findings and comments agents left are in <code>suite/assistant/Findings.json</code> and <code>suite/assistant/Comments.json</code>. These files travel with the story, so a second computer that syncs the home sees the same inbox.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/guide/connect-an-agent">Connect an agent</a></li><li><a href="/guide/guide/mate">The mate</a></li><li><a href="/guide/guide/beat-board">Beat board</a>, <a href="/guide/guide/plot-grid">Plot grid</a>, <a href="/guide/guide/threads">Threads</a>, <a href="/guide/guide/manuscript">Manuscript</a></li><li><a href="/guide/reference/keys">Keys and commands</a></li><li><a href="/guide/reference/suite-files">Files Leathercase writes</a></li></ul>',8))])}const x=s(u,[["render",m]]);export{k as __pageData,x as default};
